package medium;public class PalindromePartitioning{public static java.util.List<java.util.List<String>>partition(String s){java.util.List<java.util.List<String>>r=new java.util.ArrayList<>();backtrack(r,new java.util.ArrayList<>(),s,0);return r;}static void backtrack(java.util.List<java.util.List<String>>r,java.util.List<String>c,String s,int start){if(start==s.length()){r.add(new java.util.ArrayList<>(c));return;}for(int i=start;i<s.length();i++){if(isPalin(s,start,i)){c.add(s.substring(start,i+1));backtrack(r,c,s,i+1);c.remove(c.size()-1);}}}static boolean isPalin(String s,int l,int r){while(l<r){if(s.charAt(l++)!=s.charAt(r--))return false;}return true;}public static void main(String[]args){System.out.println("Partition works\n");}}
